/**
 * Installs plugin runtime deps using a per-plugin lockfile for deterministic,
 * auditable builds. This prevents supply-chain attacks where a transitive dep
 * is temporarily compromised on the npm registry (e.g. axios incident 2026-03-31).
 *
 * Strategy:
 * 1. Generate a full lockfile in a temp dir from the plugin's package.json deps.
 *    This pins ALL transitive deps (including axios, etc.) at registry-resolve time.
 * 2. Copy the generated lockfile into the plugin dir.
 * 3. Run `npm ci` from the temp dir (uses lockfile, ignores scripts) to install.
 *    Using the temp dir as cwd ensures the plugin's node_modules is pristine.
 */
function installPluginRuntimeDeps(pluginDir, pluginId) {
  sanitizeBundledManifestForRuntimeInstall(pluginDir);

  // Step 1: generate a lockfile in a temp dir (pins transitive deps)
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), `openclaw-plugin-lock-${pluginId}-`));
  const tmpPluginDir = path.join(tmpDir, "plugin");
  fs.mkdirSync(tmpPluginDir);

  // Copy the sanitized package.json into the temp dir
  fs.copyFileSync(path.join(pluginDir, "package.json"), path.join(tmpPluginDir, "package.json"));

  // Generate a complete lockfile by resolving all transitive deps from the registry
  // --package-lock-only: only generates package-lock.json, no node_modules
  // --ignore-scripts: prevent any malicious install scripts during resolution
  const genResult = spawnSync(
    "npm",
    ["install", "--package-lock-only", "--ignore-scripts", "--legacy-peer-deps"],
    { cwd: tmpPluginDir, encoding: "utf8", stdio: "pipe" },
  );
  if (genResult.status !== 0) {
    const output = [genResult.stderr, genResult.stdout].filter(Boolean).join("\n").trim();
    throw new Error(
      `failed to generate lockfile for ${pluginId}: ${output || "npm install --package-lock-only failed"}`,
    );
  }

  const tmpLockfile = path.join(tmpPluginDir, "package-lock.json");
  const pluginLockfile = path.join(pluginDir, "package-lock.json");

  if (!fs.existsSync(tmpLockfile)) {
    throw new Error(`lockfile not generated for ${pluginId} at ${tmpLockfile}`);
  }

  // Step 2: copy the lockfile into the plugin dir (committed per-plugin lockfile)
  fs.copyFileSync(tmpLockfile, pluginLockfile);

  // Step 3: run npm ci from the temp dir using the pinned lockfile, then copy back
  // Setting npm_config_ignore_scripts=true skips all install/postinstall scripts
  // (npm ci does not accept --ignore-scripts directly, but respects this env var)
  const ciEnv = { ...process.env, npm_config_ignore_scripts: "true" };
  const ciResult = spawnSync(
    "npm",
    ["ci", "--omit=dev", "--legacy-peer-deps"],
    { cwd: tmpPluginDir, encoding: "utf8", stdio: "pipe", env: ciEnv },
  );

  if (ciResult.status !== 0) {
    const output = [ciResult.stderr, ciResult.stdout].filter(Boolean).join("\n").trim();
    fs.rmSync(tmpDir, { recursive: true, force: true });
    throw new Error(
      `failed to install bundled runtime deps for ${pluginId}: ${output || "npm ci failed"}`,
    );
  }

  // Copy the freshly-installed, lockfile-verified node_modules back to the plugin dir
  const tmpNodeModules = path.join(tmpPluginDir, "node_modules");
  const pluginNodeModules = path.join(pluginDir, "node_modules");
  fs.rmSync(pluginNodeModules, { recursive: true, force: true });
  fs.cpSync(tmpNodeModules, pluginNodeModules, { recursive: true });

  fs.rmSync(tmpDir, { recursive: true, force: true });
}

